    const fs = require("fs");
    const formidable = require("formidable");

    const OPENAI_API_KEY = process.env.OPENAI_API_KEY;

    function parseForm(req) {
      return new Promise((resolve, reject) => {
          const form = formidable({
                multiples: true,
                      keepExtensions: true,
                            maxFileSize: 12 * 1024 * 1024
                                });

                                    form.parse(req, (err, fields, files) => {
                                          if (err) {
                                                  reject(err);
                                                          return;
                                                                }

                                                                      resolve({ fields, files });
                                                                          });
                                                                            });
                                                                            }

                                                                            function firstValue(value) {
                                                                              if (Array.isArray(value)) {
                                                                                  return value[0];
                                                                                    }

                                                                                      return value;
                                                                                      }

                                                                                      function findUploadedFile(files) {
                                                                                        // Try common field names first.
                                                                                          const preferredNames = [
                                                                                              "image",
                                                                                                  "clothing",
                                                                                                      "clothingImage",
                                                                                                          "file",
                                                                                                              "photo",
                                                                                                                  "upload"
                                                                                                                    ];

                                                                                                                      for (const name of preferredNames) {
                                                                                                                          const value = files[name];

                                                                                                                              if (!value) continue;

                                                                                                                                  if (Array.isArray(value) && value.length > 0) {
                                                                                                                                        return value[0];
                                                                                                                                            }

                                                                                                                                                if (value && typeof value === "object") {
                                                                                                                                                      return value;
                                                                                                                                                          }
                                                                                                                                                            }

                                                                                                                                                              // Fallback: use the first uploaded file.
                                                                                                                                                                for (const key of Object.keys(files)) {
                                                                                                                                                                    const value = files[key];

                                                                                                                                                                        if (Array.isArray(value) && value.length > 0) {
                                                                                                                                                                              return value[0];
                                                                                                                                                                                  }

                                                                                                                                                                                      if (value && typeof value === "object" && value.filepath) {
                                                                                                                                                                                            return value;
                                                                                                                                                                                                }
                                                                                                                                                                                                  }

                                                                                                                                                                                                    return null;
                                                                                                                                                                                                    }

                                                                                                                                                                                                    module.exports = async function handler(req, res) {
                                                                                                                                                                                                      if (req.method !== "POST") {
                                                                                                                                                                                                          return res.status(405).json({
                                                                                                                                                                                                                error: "Method not allowed"
                                                                                                                                                                                                                    });
                                                                                                                                                                                                                      }

                                                                                                                                                                                                                        if (!OPENAI_API_KEY) {
                                                                                                                                                                                                                            return res.status(500).json({
                                                                                                                                                                                                                                  error: "OPENAI_API_KEY is not configured"
                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                          let parsed;

                                                                                                                                                                                                                                            try {
                                                                                                                                                                                                                                                parsed = await parseForm(req);
                                                                                                                                                                                                                                                  } catch (error) {
                                                                                                                                                                                                                                                      console.error("Form parsing error:", error);

                                                                                                                                                                                                                                                          return res.status(400).json({
                                                                                                                                                                                                                                                                error: "Could not read the uploaded image"
                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                        const { fields, files } = parsed;

                                                                                                                                                                                                                                                                          const uploadedFile = findUploadedFile(files);

                                                                                                                                                                                                                                                                            if (!uploadedFile || !uploadedFile.filepath) {
                                                                                                                                                                                                                                                                                return res.status(400).json({
                                                                                                                                                                                                                                                                                      error: "No clothing image was uploaded"
                                                                                                                                                                                                                                                                                          });
                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                              const imagePath = uploadedFile.filepath;

                                                                                                                                                                                                                                                                                                try {
                                                                                                                                                                                                                                                                                                    const originalPrompt = firstValue(
                                                                                                                                                                                                                                                                                                          fields.prompt || fields.description || ""
                                                                                                                                                                                                                                                                                                              );

                                                                                                                                                                                                                                                                                                                  /*
                                                                                                                                                                                                                                                                                                                       * ============================================================
                                                                                                                                                                                                                                                                                                                            * CLOTHING-PRESERVATION PROMPT
                                                                                                                                                                                                                                                                                                                                 * ============================================================
                                                                                                                                                                                                                                                                                                                                      *
                                                                                                                                                                                                                                                                                                                                           * This is intentionally placed HERE, before the OpenAI request.
                                                                                                                                                                                                                                                                                                                                                * It tells the image model that the uploaded clothing design
                                                                                                                                                                                                                                                                                                                                                     * is the visual source of truth.
                                                                                                                                                                                                                                                                                                                                                          */

                                                                                                                                                                                                                                                                                                                                                              const clothingPreservationPrompt = `
                                                                                                                                                                                                                                                                                                                                                              Use the uploaded image as the PRIMARY AND STRICT VISUAL REFERENCE
                                                                                                                                                                                                                                                                                                                                                              for the clothing.

                                                                                                                                                                                                                                                                                                                                                              PRESERVE THE UPLOADED CLOTHING DESIGN AS ACCURATELY AS THE IMAGE
                                                                                                                                                                                                                                                                                                                                                              MODEL ALLOWS.

                                                                                                                                                                                                                                                                                                                                                              The garment in the uploaded image is the source of truth.

                                                                                                                                                                                                                                                                                                                                                              Preserve exactly:
                                                                                                                                                                                                                                                                                                                                                              - the garment's overall shape and construction
                                                                                                                                                                                                                                                                                                                                                              - neckline and collar shape
                                                                                                                                                                                                                                                                                                                                                              - sleeve shape, length and color
                                                                                                                                                                                                                                                                                                                                                              - cuffs and sleeve details
                                                                                                                                                                                                                                                                                                                                                              - body color and color blocking
                                                                                                                                                                                                                                                                                                                                                              - fabric appearance and texture
                                                                                                                                                                                                                                                                                                                                                              - seams and stitching
                                                                                                                                                                                                                                                                                                                                                              - hem shape
                                                                                                                                                                                                                                                                                                                                                              - proportions and placement of every graphic
                                                                                                                                                                                                                                                                                                                                                              - artwork, illustrations and characters
                                                                                                                                                                                                                                                                                                                                                              - logos, labels and printed elements that are actually present
                                                                                                                                                                                                                                                                                                                                                              - all visible words and lettering
                                                                                                                                                                                                                                                                                                                                                              - exact graphic colors
                                                                                                                                                                                                                                                                                                                                                              - exact graphic orientation
                                                                                                                                                                                                                                                                                                                                                              - exact graphic size and relative position
                                                                                                                                                                                                                                                                                                                                                              - stripes, borders, outlines and decorative details
                                                                                                                                                                                                                                                                                                                                                              - the relationship between the graphic and the garment

                                                                                                                                                                                                                                                                                                                                                              DO NOT redesign the garment.

                                                                                                                                                                                                                                                                                                                                                              DO NOT invent new clothing details.

                                                                                                                                                                                                                                                                                                                                                              DO NOT add a waistband, band, stripe, belt, ribbing, piping,
                                                                                                                                                                                                                                                                                                                                                              extra collar, extra trim or decorative panel unless it is clearly
                                                                                                                                                                                                                                                                                                                                                              present in the uploaded reference.

                                                                                                                                                                                                                                                                                                                                                              IMPORTANT:
                                                                                                                                                                                                                                                                                                                                                              If the uploaded garment does NOT have a band or waistband,
                                                                                                                                                                                                                                                                                                                                                              DO NOT ADD ONE.

                                                                                                                                                                                                                                                                                                                                                              Do not replace the uploaded graphic with a similar graphic.
                                                                                                                                                                                                                                                                                                                                                              Do not simplify the artwork.
                                                                                                                                                                                                                                                                                                                                                              Do not change the artwork's colors.
                                                                                                                                                                                                                                                                                                                                                              Do not move the artwork to another position.
                                                                                                                                                                                                                                                                                                                                                              Do not remove printed details.
                                                                                                                                                                                                                                                                                                                                                              Do not invent text.
                                                                                                                                                                                                                                                                                                                                                              Do not rewrite or reinterpret the clothing design.

                                                                                                                                                                                                                                                                                                                                                              The generated image should look like the SAME garment from the
                                                                                                                                                                                                                                                                                                                                                              uploaded reference being realistically worn by the subject.

                                                                                                                                                                                                                                                                                                                                                              Only change the person, pose, environment, lighting or fashion
                                                                                                                                                                                                                                                                                                                                                              campaign setting when requested by the user's additional prompt.

                                                                                                                                                                                                                                                                                                                                                              ${originalPrompt ? `ADDITIONAL USER REQUEST:\n${originalPrompt}` : ""}

                                                                                                                                                                                                                                                                                                                                                              The clothing design has priority over stylistic interpretation.
                                                                                                                                                                                                                                                                                                                                                              When there is a conflict between the requested scene and the
                                                                                                                                                                                                                                                                                                                                                              uploaded garment, preserve the garment design.

                                                                                                                                                                                                                                                                                                                                                              Create a photorealistic fashion photograph with realistic fabric
                                                                                                                                                                                                                                                                                                                                                              folds while keeping the garment's original design faithful to the
                                                                                                                                                                                                                                                                                                                                                              reference.
                                                                                                                                                                                                                                                                                                                                                              `;

                                                                                                                                                                                                                                                                                                                                                                  /*
                                                                                                                                                                                                                                                                                                                                                                       * Read the uploaded image.
                                                                                                                                                                                                                                                                                                                                                                            */
                                                                                                                                                                                                                                                                                                                                                                                const imageBuffer = fs.readFileSync(imagePath);

                                                                                                                                                                                                                                                                                                                                                                                    /*
                                                                                                                                                                                                                                                                                                                                                                                         * Determine MIME type.
                                                                                                                                                                                                                                                                                                                                                                                              */
                                                                                                                                                                                                                                                                                                                                                                                                  let mimeType = uploadedFile.mimetype || "image/jpeg";

                                                                                                                                                                                                                                                                                                                                                                                                      if (!/^image\/(png|jpeg|jpg|webp)$/i.test(mimeType)) {
                                                                                                                                                                                                                                                                                                                                                                                                            mimeType = "image/jpeg";
                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                    /*
                                                                                                                                                                                                                                                                                                                                                                                                                         * Create a multipart/form-data request for OpenAI.
                                                                                                                                                                                                                                                                                                                                                                                                                              */
                                                                                                                                                                                                                                                                                                                                                                                                                                  const form = new FormData();

                                                                                                                                                                                                                                                                                                                                                                                                                                      form.append("model", "gpt-image-2");
                                                                                                                                                                                                                                                                                                                                                                                                                                          form.append("prompt", clothingPreservationPrompt);
                                                                                                                                                                                                                                                                                                                                                                                                                                              form.append("quality", "high");
                                                                                                                                                                                                                                                                                                                                                                                                                                                  form.append("size", "auto");
                                                                                                                                                                                                                                                                                                                                                                                                                                                      form.append("output_format", "png");
                                                                                                                                                                                                                                                                                                                                                                                                                                                          form.append("n", "1");

                                                                                                                                                                                                                                                                                                                                                                                                                                                              form.append(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "image",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          new Blob([imageBuffer], { type: mimeType }),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                uploadedFile.originalFilename || "clothing-reference.jpg"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        console.log("Sending clothing image to OpenAI image editing...");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            console.log("Model: gpt-image-2");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                console.log("Clothing-preservation mode: ON");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    /*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         * Send the uploaded clothing image to the OpenAI Image Edit API.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const response = await fetch(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "https://api.openai.com/v1/images/edits",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      method: "POST",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              headers: {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Authorization: `Bearer ${OPENAI_API_KEY}`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        body: form
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const responseText = await response.text();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          let result;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    result = JSON.parse(responseText);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        } catch (parseError) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              console.error("OpenAI returned non-JSON:", responseText);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return res.status(502).json({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            error: "OpenAI returned an unexpected response"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!response.ok) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                console.error("OpenAI image edit error:", result);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return res.status(response.status).json({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              error:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        result?.error?.message ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  "OpenAI image generation failed"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const base64Image =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      result?.data?.[0]?.b64_json;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (!base64Image) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                console.error("No image returned:", result);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return res.status(502).json({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              error: "OpenAI did not return an image"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            /*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 * Return both formats so your frontend can use whichever
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      * one it expects.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               const dataUrl = `data:image/png;base64,${base64Image}`;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   return res.status(200).json({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         success: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               image: dataUrl,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     imageUrl: dataUrl,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           b64_json: base64Image,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 mimeType: "image/png"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       } catch (error) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           console.error("Generate error:", error);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               return res.status(500).json({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     error:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             error?.message ||
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     "Something went wrong while generating the fashion image"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           } finally {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               /*
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    * Remove the temporary uploaded file when possible.
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         */
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   if (imagePath && fs.existsSync(imagePath)) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           fs.unlinkSync(imagePath);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     } catch (cleanupError) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           console.error("Temporary file cleanup error:", cleanupError);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 };                                                                                                                     